from gapmod import K

C6 = "c-7e0b1f4942db"
C7 = "c-cbba2e56c4a9"

K("sa-tune", C6, "s-349af139def8", "Fine-tune and RAG", "C6 · Chatbot", "S1 Đổi trọng số hay đổi tài liệu", "Chatbot System Design and Building ShopAssist AI",
    ("Fine-tune đổi trọng số. RAG đổi tài liệu trong prompt", "Fine-tune changes the weights. RAG changes the documents in the prompt."),
    ("Để một bảng giá ngày mai không bị giao cho một lần fine-tune hôm nay.", "So tomorrow's price table is not handed to a fine-tune from today."),
    ("Ba tầng đã tách model và data. Fine-tune đụng model. RAG đụng data của lần gọi.", "The three layers already split model and data. Fine-tune touches the model. RAG touches the data of the call."),
    ("đổi trọng số", "change the weights"), ("đổi tài liệu", "change the documents"),
    ("Fine-tune chỉnh trọng số bằng các ví dụ huấn luyện. RAG để nguyên trọng số và nhét các đoạn tài liệu vào prompt rồi mới viết.", "Fine-tune adjusts weights with training examples. RAG leaves the weights and puts document passages into the prompt before writing."),
    ("Giá đổi mỗi sáng. Fine-tune đêm qua không biết giá sáng nay. RAG chỉ biết nếu đoạn giá sáng nay được đưa vào lần gọi.", "The price changes every morning. Last night's fine-tune does not know this morning's price. RAG only knows if this morning's price passage is put into the call."),
    ("Tài liệu đổi thường: RAG. Giọng văn ổn định, ít khi đổi sự thật: lúc đó mới xét fine-tune.", "Documents that change often: RAG. A stable voice, and the facts rarely change: only then consider a fine-tune."),
    ("Ví dụ minh họa: chính sách đổi trả sửa một câu. Việc cần là câu mới nằm trong tài liệu được tìm. Huấn luyện lại cả mô hình vì một câu là nhầm tầng.", "Illustration: the return policy changes one sentence. The job is for the new sentence to sit in the document that gets retrieved. Retraining the whole model for one sentence is the wrong layer."),
    [("Sự thật đổi theo ngày: đừng fine-tune để nhớ sự thật đó.", "A fact that changes by the day: don't fine-tune to memorize that fact."), ("RAG chỉ đúng nếu đoạn được tìm là đoạn đang hiệu lực.", "RAG is only right if the retrieved passage is the one that is in force."), ("Fine-tune không thay một cơ sở dữ liệu.", "A fine-tune does not replace a database.")],
    ("Fine-tune không đảm bảo mô hình thuộc lòng một bảng để bạn tra như khóa chính. Nó đổi cách viết. RAG không làm mô hình «hiểu» tài liệu. Nó chỉ cho lần gọi thấy một vài đoạn. Cả hai đều không phải một transaction của giá. Giá vẫn nên ở một bảng, và một công cụ đọc bảng nếu sản phẩm cần một số đúng.", "A fine-tune does not guarantee the model memorized a table you can look up like a primary key. It changes how it writes. RAG does not make the model “understand” the documents. It only lets this call see a few passages. Neither is a transaction of the price. The price should stay in a table, and a tool should read the table if the product needs a correct number."),
    ("Ngày mai đổi giá thì đêm qua huấn luyện không phải là kế hoạch.", "If the price changes tomorrow, training last night is not the plan."),
)
K("sa-react", C6, "s-349af139def8", "ReAct", "C6 · Chatbot", "S1 Làm một việc rồi mới nhìn", "Chatbot System Design and Building ShopAssist AI",
    ("Nghĩ, gọi một công cụ, nhìn kết quả. Đừng bịa kết quả công cụ", "Think, call a tool, look at the result. Don't invent the tool's result."),
    ("Để một câu «tôi đã tra catalog» không được tính nếu không có lần gọi catalog.", "So a sentence “I looked at the catalog” does not count if there was no catalog call."),
    ("Fine-tune và RAG đã là hai cách đổi cái mô hình thấy. ReAct là một vòng: viết một bước, gọi công cụ, đọc cái công cụ trả.", "Fine-tune and RAG were two ways to change what the model sees. ReAct is a loop: write a step, call a tool, read what the tool returns."),
    ("có kết quả công cụ", "there is a tool result"), ("tự bịa đã tra", "invents that it looked"),
    ("ReAct là reason rồi act bằng một công cụ, rồi observe đúng cái công cụ trả về. Quan sát không phải một câu mô hình ước.", "ReAct is reason, then act with a tool, then observe exactly what the tool returned. The observation is not a sentence the model guesses."),
    ("Không có dòng log gọi catalog thì không được nói tồn kho. Dù câu chữ rất chắc.", "With no log line that called the catalog, you may not state the stock. Even if the sentence is very sure."),
    ("Mỗi sự thật từ hệ thống phải có một lần gọi và một kết quả.", "Every fact from a system needs one call and one result."),
    ("Ví dụ minh họa: hỏi còn hàng không. Bước act là gọi catalog theo mã. Observe là số catalog trả. Không có bước đó thì câu trả lời phải nói chưa tra, không được bịa «còn 3».", "Illustration: the question is whether it is in stock. The act step calls the catalog by code. The observation is the number the catalog returns. Without that step the answer must say it has not looked, and it may not invent “3 left”."),
    [("Log phải có tên công cụ và kết quả.", "The log needs the tool name and the result."), ("Kết quả lạ: trả về kết quả đó, đừng sửa cho đẹp.", "A strange result: return that result. Don't edit it to look nice."), ("Hết số bước cho phép thì dừng và nói chưa xong.", "When the step cap is hit, stop and say it is not finished.")],
    ("Vòng này có thể lặp. Không có trần số bước thì nó tiêu token và không bao giờ trả lời. Trần là một giới hạn sản phẩm, cùng họ với một constraint không được tiêu hai lần. Công cụ trả lỗi thì observe là cái lỗi, không phải một kết quả đẹp mô hình điền vào.", "This loop can repeat. With no cap on steps it spends tokens and never answers. The cap is a product limit, the same family as a constraint you cannot spend twice. If the tool returns an error, the observation is that error, not a pretty result the model fills in."),
    ("Không có log thì chưa tra.", "No log means it has not looked."),
)
K("sa-stage", C6, "s-792a5182c169", "ShopAssist stages", "C6 · Chatbot", "S2 Ba chặng", "Chatbot System Design and Building ShopAssist AI",
    ("Ba chặng: nói từ prompt, gọi catalog, rồi chấm các ca. Đừng bịa một cuộc thoại", "Three stages: talk from the prompt, call the catalog, then score cases. Don't invent a transcript."),
    ("Để một bài tập ShopAssist không bị thay bằng một kịch bản bịa.", "So a ShopAssist assignment is not replaced by an invented script."),
    ("ReAct đã là vòng gọi công cụ. ShopAssist trong giáo trình đi ba chặng, không có một transcript mẫu để học thuộc.", "ReAct was the tool-calling loop. ShopAssist in the syllabus walks three stages. There is no sample transcript to memorize."),
    ("ba chặng", "three stages"), ("một thoại bịa", "an invented transcript"),
    ("Chặng một là nói dựa trên prompt. Chặng hai là công cụ và catalog. Chặng ba là chấm các ca đã có. Sổ không bịa lời thoại của một cuộc gọi.", "Stage one is talking from the prompt. Stage two is the tool and the catalog. Stage three is scoring cases you already have. The notebook does not invent the lines of a call."),
    ("Một đoạn «khách nói: cho tôi gói 2 triệu» không có trong tài liệu thì đừng thêm vào để bài dễ chấm.", "A line “the customer said: give me the 2-million package” is not in the material, so don't add it to make the case easier to score."),
    ("Giữ đúng ba chặng. Thiếu log của chặng nào thì chặng đó chưa xảy ra.", "Keep the three stages. A missing log for a stage means that stage has not happened."),
    ("Ví dụ minh họa: chặng một không có catalog thì không được nói giá. Chặng hai mới có kết quả catalog. Chặng ba so các ca với một thước bạn viết trước, không phải với một thoại bịa.", "Illustration: stage one has no catalog, so it may not state a price. Stage two is where the catalog result exists. Stage three compares cases to a measure you wrote beforehand, not to an invented transcript."),
    [("Chặng một: chỉ cái có trong prompt.", "Stage one: only what is in the prompt."), ("Chặng hai: mọi số hàng hóa đến từ log công cụ.", "Stage two: every stock or price number comes from a tool log."), ("Chặng ba: chấm ca đã viết, đừng thêm ca cho đủ đẹp.", "Stage three: score the cases you wrote. Don't add cases to make it look good.")],
    ("Giáo trình có ba buổi giới thiệu ba chặng. Không buổi nào cấp một transcript chuẩn. Tự viết một cuộc thoại rồi chấm cuộc thoại đó là chấm một chuyện bạn vừa bịa. Các ca ở chặng ba phải được viết trước, có kết quả đúng lấy từ catalog hoặc từ chính sách, không lấy từ một lần model trả lời hay.", "The syllabus introduces three stages. None of them hands you a canonical transcript. Writing a conversation and then scoring that conversation is scoring something you just invented. The cases in stage three have to be written beforehand, with the correct result taken from the catalog or the policy, not from a fluent model reply."),
    ("Không có transcript mẫu. Đừng sản xuất một cái.", "There is no sample transcript. Don't manufacture one."),
)
K("sa-tool", C6, "s-91022c565b13", "Catalog tool", "C6 · Chatbot", "S3 Catalog", "Chatbot System Design and Building ShopAssist AI",
    ("Giá và tồn kho đến từ catalog. Không đến từ một câu hay", "Price and stock come from the catalog. Not from a fluent sentence."),
    ("Để chặng hai không bị viết thành một đoạn văn không có mã sản phẩm.", "So stage two is not written as a paragraph with no product code."),
    ("Ba chặng đã có chỗ của catalog. Chặng này là chỗ số được phép xuất hiện, và chỉ từ công cụ.", "The three stages already have a place for the catalog. This stage is where a number is allowed to appear, and only from the tool."),
    ("số từ catalog", "a number from the catalog"), ("số từ câu hay", "a number from a fluent sentence"),
    ("Công cụ catalog nhận một mã và trả các trường đang có: giá, tồn, điều kiện. Thiếu mã thì không có số.", "The catalog tool takes a code and returns the fields that exist: price, stock, conditions. No code, no number."),
    ("Model viết «khoảng 2 triệu» trong khi catalog không được gọi. Đó không phải một ước lượng. Đó là một số bịa.", "The model writes “about 2 million” while the catalog was not called. That is not an estimate. That is an invented number."),
    ("Không có một dòng catalog thì không có giá trong câu trả lời.", "With no catalog line, there is no price in the answer."),
    ("Ví dụ minh họa: mã A12 trả giá và tồn. Câu trả lời được nhắc lại đúng các trường đó. Hết mã A12 mà khách hỏi một gói không có mã thì câu trả lời là không thấy mã, không phải một giá gần.", "Illustration: code A12 returns a price and a stock. The answer repeats those fields. If there is no code A12 and the customer asks for a package with no code, the answer is that the code was not found, not an approximate price."),
    [("Gọi bằng mã, đừng gọi bằng một tính từ.", "Call with a code, not with an adjective."), ("Trả lại đúng trường catalog trả.", "Return the fields the catalog returned."), ("Không thấy mã: nói không thấy. Đừng nội suy giá.", "Code not found: say not found. Don't interpolate a price.")],
    ("Catalog là một hệ thống, cùng luật với một bảng SQL: không có dòng thì không có số, không phải số 0. Một công cụ lỗi trả lỗi. Bọc lỗi thành «tạm hết hàng» là đổi nghĩa. Chính sách hoàn tiền cũng là một tài liệu, không phải một giá. Đừng lấy giá từ chính sách nếu catalog mới là nguồn giá.", "A catalog is a system, the same law as a SQL table: no row means no number, not a number 0. A tool error returns an error. Wrapping the error as “temporarily out of stock” changes the meaning. A refund policy is also a document, not a price. Don't take the price from the policy if the catalog is the source of price."),
    ("Không có mã thì không có giá.", "No code, no price."),
)
K("sa-score", C6, "s-310c39a3e81f", "Score cases", "C6 · Chatbot", "S4 Chấm ca", "Chatbot System Design and Building ShopAssist AI",
    ("Chấm các ca đã viết. Vài lần trả lời giống nhau không phải sự thật", "Score the cases you wrote. Several similar replies are not the truth."),
    ("Để self-consistency không bị đọc thành đã kiểm xong catalog.", "So self-consistency is not read as the catalog having been checked."),
    ("Catalog đã là nguồn số. Chặng ba hỏi các ca có bám nguồn đó không, không hỏi mô hình có tự tin không.", "The catalog is already the source of numbers. Stage three asks whether the cases stick to that source, not whether the model sounds sure."),
    ("giống nhau", "they agree"), ("không phải đã đúng", "not the same as correct"),
    ("Self-consistency là chạy vài lần rồi lấy câu hay gặp. Các lần cùng bịa một giá thì câu hay gặp vẫn là giá bịa.", "Self-consistency is several runs, then the sentence that shows up most. If the runs invent the same price, the frequent sentence is still an invented price."),
    ("Năm lần cùng nói «còn hàng» trong khi catalog nói hết thì sự nhất trí là năm lần sai.", "Five runs all say “in stock” while the catalog says none left. The agreement is five wrong runs."),
    ("Thước của một ca là kết quả catalog hoặc câu trong chính sách. Không phải số lần model lặp.", "The measure of a case is the catalog result or the sentence in the policy. Not how often the model repeats itself."),
    ("Ví dụ minh họa: ca viết trước: mã A12, catalog trả hết hàng. Model nói còn. Ca đó sai, dù nói chắc. Không thêm một ca mới cho đủ điểm.", "Illustration: a case written beforehand: code A12, the catalog returns out of stock. The model says in stock. That case is wrong, however sure it sounds. Don't add a new case to fill the score."),
    [("Ca được viết trước, kèm kết quả đúng từ nguồn.", "Cases are written beforehand, with the correct result from the source."), ("Chấm từng ca, đừng chấm độ mượt.", "Score each case. Don't score smoothness."), ("Vài lần đồng ý: chỉ là đồng ý. Vẫn đối chiếu nguồn.", "Several runs agreeing: that is only agreement. Still check the source.")],
    ("Self-consistency giảm một kiểu nhiễu của cách chọn token. Nó không tạo một nguồn. Một ca không có kết quả đúng từ catalog hoặc từ đoạn chính sách thì không chấm được, và cũng không được bịa kết quả đúng cho có. Đừng sản xuất transcript để có thêm ca.", "Self-consistency reduces one kind of noise in how tokens are chosen. It does not create a source. A case with no correct result from the catalog or from the policy passage cannot be scored, and you also may not invent a correct result so that you can. Don't manufacture a transcript to get more cases."),
    ("Đồng ý với nhau không phải đồng ý với catalog.", "Agreeing with each other is not agreeing with the catalog."),
)

K("rag-why", C6, "s-62d4df64cdbe", "Why RAG", "C6 · RAG", "S1 File không nằm trong mô hình", "Retrieval Augmented Generation with LlamaIndex",
    ("File của bạn không nằm sẵn trong mô hình", "Your file is not already inside the model."),
    ("Để một chính sách nội bộ không bị hỏi suông rồi tin câu trả lời.", "So an internal policy is not asked in the open and then believed."),
    ("Fine-tune đã không phải chỗ của một tài liệu đổi hàng ngày. RAG là cách đưa đúng đoạn vào lần gọi.", "Fine-tune was already the wrong place for a document that changes daily. RAG is how the right passage gets into the call."),
    ("file ở ngoài", "the file is outside"), ("đoạn được đưa vào", "a passage is put in"),
    ("RAG tìm một vài đoạn rồi để mô hình viết có các đoạn đó trong prompt. Không tìm thì mô hình không thấy file.", "RAG finds a few passages and lets the model write with those passages in the prompt. If it does not find them, the model does not see the file."),
    ("Hỏi chính sách hoàn tiền mà không retrieval thì câu trả lời không đứng trên chính sách của công ty.", "Ask the refund policy with no retrieval and the answer does not stand on the company's policy."),
    ("Muốn bám file thì phải có bước tìm, và phải thấy đoạn nào đã vào prompt.", "To stick to a file there must be a retrieval step, and you must see which passage entered the prompt."),
    ("Ví dụ minh họa: một file PDF nội bộ. Lần gọi không kèm đoạn nào của file đó thì mọi câu về file đó là một câu không nguồn, dù nhắc chữ RAG.", "Illustration: an internal PDF. A call that includes no passage from that file makes every sentence about that file a sentence with no source, even if you say the word RAG."),
    [("Kiểm tra đoạn nào thực sự vào prompt.", "Check which passage actually entered the prompt."), ("Không có đoạn: đừng trả lời như thể đã đọc file.", "No passage: don't answer as if the file had been read."), ("File đổi thì bước tìm phải thấy bản mới.", "If the file changes, retrieval has to see the new version.")],
    ("RAG không nhét cả file vào trọng số. Nó thất bại theo hai kiểu: tìm nhầm đoạn, hoặc tìm đúng mà câu viết vẫn thêm một số không có trong đoạn. Cả hai đều phải chấm bằng ca, không bằng một demo nói được.", "RAG does not put the whole file into the weights. It fails in two ways: it retrieves the wrong passage, or it retrieves the right one and the writing still adds a number that is not in the passage. Both have to be scored with cases, not with a demo that can talk."),
    ("Nhắc chữ RAG không có nghĩa là file đã được đọc.", "Saying RAG does not mean the file was read."),
)
K("rag-emb", C6, "s-62d4df64cdbe", "Embeddings", "C6 · RAG", "S1 Gần nhau", "Retrieval Augmented Generation with LlamaIndex",
    ("Gần trong embedding không phải trùng từ khóa, cũng không phải đúng", "Near in an embedding is not a keyword match, and it is not correct."),
    ("Để đoạn «gần nghĩa» không bị dùng như một điều khoản đúng.", "So a “nearby in meaning” passage is not used as the correct clause."),
    ("RAG cần một cách tìm. Embedding là một cách tìm theo hướng của câu, không phải theo khóa chính.", "RAG needs a way to search. An embedding searches by the direction of the sentence, not by a primary key."),
    ("gần hướng", "near in direction"), ("không phải đúng điều khoản", "not the correct clause"),
    ("Embedding đặt một đoạn chữ thành một vectơ. Đoạn gần nhau thì góc gần. Gần không có nghĩa là cùng một điều khoản, và cũng không có nghĩa là chứa đúng từ bạn gõ.", "An embedding turns a passage into a vector. Nearby passages have a nearby angle. Near does not mean the same clause, and it does not mean it contains the exact word you typed."),
    ("«Được hoàn khi lỗi của shop» và «không được hoàn khi lỗi của shop» có thể nằm gần nhau vì cùng các chữ. Gần mà trái nghĩa.", "“Refunds are allowed when the shop is at fault” and “refunds are not allowed when the shop is at fault” can sit near each other because they share words. Near, and opposite."),
    ("Coi điểm gần là một ứng viên. Đọc đoạn. Đừng coi điểm gần là một quyết định.", "Treat a near score as a candidate. Read the passage. Don't treat the near score as a decision."),
    ("Ví dụ minh họa: câu hỏi có chữ hoàn tiền. Đoạn được kéo lên có thể là mục quảng cáo có chữ hoàn tiền, không phải điều khoản. Điểm cao hơn không vá việc đó.", "Illustration: the question contains the word refund. The passage pulled up might be an ad that contains the word refund, not the clause. A higher score does not patch that."),
    [("Đọc đoạn trước khi trả lời, đừng đọc mỗi điểm.", "Read the passage before you answer. Don't read only the score."), ("Từ khóa đúng vẫn có thể là đoạn sai. Nhìn cả câu.", "The right keyword can still be the wrong passage. Read the whole sentence."), ("Hai đoạn trái nghĩa cùng gần: đừng lấy đoạn điểm cao hơn một cách máy móc.", "Two opposite passages both near: don't take the higher score mechanically.")],
    ("Một embedding không phải một chỉ mục khóa. Nó cũng không phải một kiểm định. Hai câu cùng chủ đề sẽ gần dù một câu phủ định câu kia. Keyword search thì ngược lại: đúng chữ, có thể sai ý, nhưng ít nhất chữ có mặt. Cả hai đều là ứng viên, không phải sự thật.", "An embedding is not a key index. It is also not a test. Two sentences on the same topic sit near each other even if one negates the other. Keyword search is the other way: the exact word, possibly the wrong idea, but at least the word is present. Both are candidates, not the truth."),
    ("Gần không phải đúng. Trái nghĩa vẫn có thể gần.", "Near is not correct. An opposite can still be near."),
)
K("rag-chunk", C6, "s-62d4df64cdbe", "Chunks", "C6 · RAG", "S1 Cắt đoạn", "Retrieval Augmented Generation with LlamaIndex",
    ("Cắt đoạn là cắt nghĩa. Một điều khoản bị xẻ đôi thì không còn là điều khoản", "Cutting a passage cuts the meaning. A clause split in half is no longer the clause."),
    ("Để một chunk ngắn không bị tưởng là «đủ ý» chỉ vì nó vừa một lần tìm.", "So a short chunk is not treated as “the whole idea” just because it fit one search."),
    ("Embedding tìm trên các đoạn bạn đã cắt. Cắt sai thì tìm đúng đoạn vẫn là một nửa câu.", "An embedding searches the passages you already cut. Cut wrong and the right hit is still half a sentence."),
    ("còn cả điều khoản", "the whole clause"), ("chỉ còn một nửa", "only a half remains"),
    ("Chunk là mảnh bạn cắt từ file để tìm và để nhét vào prompt. Mảnh cụt mất điều kiện phía sau thì mô hình chỉ thấy nửa luật.", "A chunk is a piece you cut from the file to search and to put in the prompt. A piece that loses the condition after it means the model only sees half the rule."),
    ("«Được hoàn tiền» nằm một mảnh, «trừ khi đã qua 7 ngày» nằm mảnh sau không được tìm. Câu trả lời sẽ cho hoàn.", "“Refunds are allowed” sits in one piece, “unless 7 days have passed” sits in the next piece and is not retrieved. The answer will allow the refund."),
    ("Cắt sao cho một điều khoản còn nguyên trong một mảnh, hoặc chấp nhận đưa các mảnh liền kề.", "Cut so that one clause stays whole in one piece, or accept that you must bring the neighboring pieces."),
    ("Ví dụ minh họa: một mục 8 dòng. Cắt 2 dòng một mảnh thì điều kiện ở dòng 6 không đi cùng lời hứa ở dòng 1. Hỏi về hoàn tiền có thể chỉ thấy dòng 1.", "Illustration: a section of 8 lines. Cut into pieces of 2 lines and the condition on line 6 does not travel with the promise on line 1. A refund question might only see line 1."),
    [("Một điều khoản một mảnh, nếu nó vừa cửa sổ.", "One clause per piece, if it fits the window."), ("Mảnh có lời hứa thì kéo cả mảnh điều kiện ngay sau.", "A piece with a promise should bring the condition piece right after it."), ("Đừng cắt giữa một câu để cho đủ một con số token đẹp.", "Don't cut in the middle of a sentence to hit a pretty token count.")],
    ("Chunk nhỏ thì tìm dễ trúng một chữ và dễ mất điều kiện. Chunk lớn thì tốn token và kéo theo đoạn không liên quan. Không có kích thước đúng cho mọi file. Có một kiểm tra: các ca chấm phải gồm những câu mà điều kiện nằm sau lời hứa. Rớt các ca đó là đang cắt mất nghĩa.", "A small chunk is easy to hit with one word and easy to lose a condition from. A large chunk costs tokens and drags in unrelated text. There is no size that is right for every file. There is a check: the scoring cases must include sentences whose condition sits after the promise. Failing those cases means the cut is dropping the meaning."),
    ("Một nửa điều khoản không phải một điều khoản ngắn hơn.", "Half a clause is not a shorter clause."),
)
K("rag-vec", C6, "s-f63690f6da9c", "Nearest", "C6 · RAG", "S2 Gần nhất chưa phải đúng", "Retrieval Augmented Generation with LlamaIndex",
    ("Đoạn gần nhất không phải đoạn đúng", "The nearest passage is not the correct passage."),
    ("Để top-1 không được tự động trở thành câu trả lời.", "So top-1 does not automatically become the answer."),
    ("Đã biết gần không phải đúng, và cắt có thể mất nửa câu. Bước xây ứng dụng vẫn hay lấy top-1 rồi viết.", "You already know near is not correct, and a cut can lose half a sentence. The application step still often takes top-1 and writes."),
    ("top-1", "top-1"), ("chưa đối chiếu", "not checked yet"),
    ("Vector store trả các đoạn gần nhất. Gần nhất trong kho hiện tại vẫn có thể là đoạn sai, đoạn cũ, hoặc một nửa điều khoản.", "A vector store returns the nearest passages. The nearest in the current store can still be the wrong passage, an old passage, or half a clause."),
    ("Điểm 0,91 của một mục quảng cáo không thắng điểm 0,86 của đúng điều khoản, nếu bạn không đọc.", "A score of 0.91 on an ad does not beat a score of 0.86 on the real clause, if you don't read."),
    ("Lấy vài đoạn, đọc, rồi mới viết. Top-1 không phải một kết luận.", "Take a few passages, read, then write. Top-1 is not a conclusion."),
    ("Ví dụ minh họa: kho có cả FAQ marketing lẫn điều khoản. Câu hỏi dùng chữ của FAQ. Top-1 là FAQ. Điều khoản đứng thứ hai. Trả lời theo top-1 là trả lời nhầm tài liệu.", "Illustration: the store has both a marketing FAQ and the clause. The question uses the FAQ's words. Top-1 is the FAQ. The clause is second. Answering from top-1 answers the wrong document."),
    [("Lấy nhiều hơn một đoạn khi các điểm sát nhau.", "Take more than one passage when the scores are close."), ("Nói đoạn nào được dùng trong câu trả lời.", "Say which passage was used in the answer."), ("Đoạn không chứa được câu trả lời: nói không thấy, đừng lấy đoạn gần.", "If no passage contains the answer, say so. Don't take a near one.")],
    ("Nearest neighbor là một thứ tự trong kho bạn đã nạp, không phải một thứ tự sự thật. Một kho thiếu điều khoản thì điều khoản không bao giờ thắng. Thêm re-rank phía sau là một lần đọc thứ hai, vẫn không biến một đoạn sai thành đúng. Ca chấm phải có những câu mà top-1 cố ý là đoạn cạm bẫy.", "Nearest neighbor is an order inside the store you loaded, not an order of truth. A store missing the clause means the clause never wins. A re-rank afterwards is a second reading, and it still does not turn a wrong passage into the right one. Scoring cases must include questions where top-1 is deliberately a trap passage."),
    ("Gần nhất trong một kho thiếu vẫn là thiếu.", "The nearest thing in a store that lacks the clause is still a lack."),
)
K("rag-idx", C6, "s-f63690f6da9c", "Stale index", "C6 · RAG", "S2 Mục lục cũ", "Retrieval Augmented Generation with LlamaIndex",
    ("Đổi file mà không làm lại mục lục thì lần tìm thấy bản cũ", "Change the file and skip re-indexing, and the search sees the old version."),
    ("Để một chính sách vừa sửa không bị trả lời bằng đoạn đã xóa.", "So a policy you just edited is not answered with the passage you deleted."),
    ("Top-1 đã có thể sai trong một kho đúng. Một kho cũ thì top-1 là sự thật của hôm qua.", "Top-1 can already be wrong in a correct store. An old store means top-1 is yesterday's truth."),
    ("file đã đổi", "the file changed"), ("mục lục chưa đổi", "the index has not"),
    ("Index là bản các đoạn đã cắt và đã embedding. Sửa file nguồn không sửa index, trừ khi bạn xây lại.", "The index is the cut, embedded passages. Editing the source file does not edit the index, unless you build it again."),
    ("Sửa một câu trong PDF rồi hỏi ngay. Câu mới không có trong index. Câu trả lời bám câu cũ.", "Edit one sentence in the PDF and ask immediately. The new sentence is not in the index. The answer sticks to the old sentence."),
    ("Mỗi lần nguồn đổi là một lần xây lại, hoặc một cách ghi phiên bản.", "Every source change is a rebuild, or a way of recording the version."),
    ("Ví dụ minh họa: điều khoản 7 ngày thành 14 ngày lúc 9 giờ. Index xây lúc 8 giờ. Cả buổi sáng bot nói 7. Không phải mô hình ngoan cố. Là mục lục cũ.", "Illustration: a 7-day clause becomes 14 days at 9am. The index was built at 8am. All morning the bot says 7. The model is not being stubborn. The index is old."),
    [("Ghi giờ xây index cạnh giờ sửa file.", "Write the index build time next to the file edit time."), ("File mới hơn index: đừng trả lời như bản mới.", "If the file is newer than the index, don't answer as the new version."), ("Một bản index cho một bản file. Đừng trộn.", "One index for one version of the file. Don't mix them.")],
    ("LlamaIndex và các thư viện cùng họ không theo dõi hộ bạn mọi lần sửa file. Một folder được «watch» chỉ khi bạn đặt việc đó. Không đặt thì index là một snapshot. Đây cùng một ý với refresh của Power BI: im lặng là bản cũ. Ca chấm nên có một ca cố ý dùng file mới hơn index.", "LlamaIndex and the libraries in the same family do not watch every file edit for you. A folder is watched only if you set that up. If you don't, the index is a snapshot. Same idea as a Power BI refresh: silence is the old version. Scoring cases should include one case that deliberately uses a file newer than the index."),
    ("Sửa file không phải sửa mục lục.", "Editing the file is not editing the index."),
)
K("rag-rank", C6, "s-f63690f6da9c", "Re-rank", "C6 · RAG", "S2 Đọc lại", "Retrieval Augmented Generation with LlamaIndex",
    ("Re-rank là một lần đọc lại. Không phải một nguồn mới", "Re-rank is a second reading. Not a new source."),
    ("Để một điểm re-rank cao không thành một điều khoản không có trong kho.", "So a high re-rank score does not become a clause that is not in the store."),
    ("Index cũ đã là một lỗi. Re-rank trên một index cũ chỉ sắp xếp lại các đoạn cũ.", "A stale index is already a failure. Re-ranking a stale index only reorders the old passages."),
    ("xếp lại đoạn đang có", "reorders what you have"), ("không thêm đoạn", "it adds no passage"),
    ("Re-ranker chấm lại một danh sách đoạn đã tìm. Đoạn không nằm trong danh sách đó không được chấm.", "A re-ranker scores again a list of passages already retrieved. A passage that is not in that list does not get scored."),
    ("Top-20 toàn là FAQ. Re-rank chọn FAQ nghe hợp nhất. Điều khoản không có trong 20 thì không thắng.", "The top 20 are all FAQ. The re-rank picks the FAQ that sounds best. A clause that is not in the 20 does not win."),
    ("Re-rank sau khi đã có ứng viên đáng đọc. Đừng hy vọng nó tìm hộ một đoạn chưa được tìm.", "Re-rank after you already have candidates worth reading. Don't hope it finds a passage that was never retrieved."),
    ("Ví dụ minh họa: 20 đoạn, đúng điều khoản đứng thứ 15 vì embedding. Re-rank có thể kéo nó lên. Nếu bước tìm chỉ giữ 5 đoạn và điều khoản đứng thứ 15, re-rank không thấy nó.", "Illustration: 20 passages, the real clause sits at 15 because of the embedding. A re-rank might pull it up. If retrieval only kept 5 and the clause was 15th, the re-rank never sees it."),
    [("Giữ đủ ứng viên trước khi re-rank.", "Keep enough candidates before you re-rank."), ("Vẫn đọc đoạn thắng, đừng đọc mỗi điểm mới.", "Still read the winning passage. Don't read only the new score."), ("Kho không có đoạn đúng thì đừng re-rank để tự an ủi.", "If the store has no correct passage, don't re-rank to comfort yourself.")],
    ("Re-rank là một mô hình khác chấm độ hợp của câu hỏi và đoạn. Nó vẫn là điểm, không phải một khóa chính. Một đoạn trái nghĩa vẫn có thể được chấm cao nếu chữ khớp. Ca chấm của re-rank là những ca top-1 embedding sai mà đoạn đúng vẫn còn trong danh sách đưa vào re-rank. Không có đoạn đúng trong danh sách thì re-rank không có gì để cứu.", "Re-rank is another model scoring how a question and a passage fit. It is still a score, not a primary key. An opposite passage can still score high if the words match. The scoring cases for re-rank are the ones where the embedding's top-1 is wrong and the right passage is still in the list handed to the re-ranker. If the right passage is not in the list, re-rank has nothing to save."),
    ("Xếp lại không đẻ ra đoạn còn thiếu.", "Reordering does not give birth to the missing passage."),
)
K("rag-near", C6, "s-f92450e4d584", "A demo is not a proof", "C6 · RAG", "S1 Demo tìm kiếm", "Additional Resources - RAG Pre-Requisites",
    ("Một demo tìm được đoạn chưa phải một đánh giá", "A demo that finds a passage is not an evaluation."),
    ("Để một lần chạy trên sân khấu không thay các ca đã viết.", "So one run on a stage does not replace the cases you wrote."),
    ("Embedding đã là độ gần. Một buổi demo chỉ cho thấy một câu hỏi may được đoạn hợp.", "An embedding is already nearness. A demo session only shows that one lucky question got a fitting passage."),
    ("một lần chạy", "one run"), ("một bộ ca", "a set of cases"),
    ("Demo là một câu hỏi bạn chọn vì nó chạy được. Bộ ca gồm cả câu cố ý khó: trái nghĩa, điều khoản bị cắt, file mới hơn index.", "A demo is a question you picked because it runs. A case set includes questions that are hard on purpose: an opposite, a cut clause, a file newer than the index."),
    ("Một câu trên slide ra đúng đoạn. Ba câu khách sẽ hỏi thì chưa được nhìn. Demo không kể ba câu đó.", "One question on the slide returns the right passage. The three questions a customer will ask have not been looked at. The demo does not mention those three."),
    ("Giữ bộ ca. Demo chỉ là một câu trong bộ đó, nếu nó đáng nằm trong bộ.", "Keep the case set. A demo is one question in that set, if it deserves to be in the set."),
    ("Ví dụ minh họa: buổi Semantic Search Demonstration cho một câu. Việc của bạn là viết thêm các ca mà độ gần sẽ phản bội. Không có các ca đó thì buổi demo không thành một kết quả.", "Illustration: a semantic-search demonstration gives you one question. Your job is to write more cases where nearness will betray you. Without those cases the demonstration is not a result."),
    [("Đừng chọn câu demo làm thước.", "Don't make the demo question the measure."), ("Thêm ca trái nghĩa và ca điều kiện nằm sau.", "Add an opposite case and a case whose condition sits later."), ("Một lần đúng không cộng thành một tỷ lệ.", "One correct run does not add up to a rate.")],
    ("Buổi này trong giáo trình là demonstration. Nó không cấp một bộ ca. Tự coi demo là đánh giá là cùng lỗi với accuracy trên một lớp đông: một số đẹp, sai việc. Không bịa transcript. Không bịa một tỷ lệ chính xác cho buổi demo.", "This session in the syllabus is a demonstration. It does not hand you a case set. Treating the demo as an evaluation is the same mistake as accuracy on a crowded class: a pretty number, the wrong job. Don't invent a transcript. Don't invent an accuracy rate for the demonstration."),
    ("Một câu chạy được không phải một tỷ lệ.", "One question that runs is not a rate."),
)
K("rag-store", C6, "s-4df79c3f1e30", "Collections", "C6 · RAG", "S2 Một kho một tên", "Additional Resources - RAG Pre-Requisites",
    ("Một collection là một kho có tên. Kho khác không tự được tìm", "A collection is a named store. Another store is not searched on its own."),
    ("Để chính sách nằm ở kho A không bị tưởng là đã tìm khi lần gọi chỉ mở kho B.", "So a policy that lives in store A is not assumed searched when the call only opened store B."),
    ("Demo đã không phải đánh giá. Kho là chỗ các đoạn thực sự nằm, và lần gọi phải chỉ đúng tên kho.", "A demo was not an evaluation. The store is where the passages actually sit, and the call has to name the right store."),
    ("đúng tên kho", "the right store name"), ("kho bên cạnh không được hỏi", "the store next to it is not asked"),
    ("Vector store giữ các đoạn theo collection. Hỏi một collection thì các collection kia đứng im.", "A vector store keeps passages by collection. Ask one collection and the others sit still."),
    ("Giá ở collection catalog, chính sách ở collection policy. Lần gọi chỉ mở catalog thì không thấy chính sách, dù hai kho cùng một máy.", "Prices live in the catalog collection, the policy in the policy collection. A call that only opens catalog does not see the policy, even if both stores are on the same machine."),
    ("Nói tên kho trong log. Đừng nói «đã tìm vector store» như thể chỉ có một kho.", "Say the store's name in the log. Don't say “searched the vector store” as if there were only one."),
    ("Ví dụ minh họa: Chroma collection `policy-2026-10`. Lần gọi trỏ `policy-2026-09`. Câu trả lời bám tháng 9. Không phải embedding hỏng.", "Illustration: a Chroma collection `policy-2026-10`. The call points at `policy-2026-09`. The answer sticks to September. The embedding is not broken."),
    [("Mỗi việc một tên kho, ghi trong log.", "Each job names a store, and the log says it."), ("Đừng tìm mọi kho cho chắc. Bạn sẽ trộn phiên bản.", "Don't search every store just in case. You will mix versions."), ("Xóa một collection là mất các đoạn đó trong lần tìm, không phải xóa file gốc.", "Deleting a collection removes those passages from search. It does not delete the source file.")],
    ("Chroma và các kho cùng kiểu tách collection để các việc không trộn. Trộn là một lựa chọn nguy hiểm, không phải một mặc định an toàn. Một collection không có đoạn nào thì lần tìm trả rỗng. Rỗng không phải một đoạn gần. Đừng để mô hình viết tiếp trên một lần tìm rỗng.", "Chroma and stores of the same kind separate collections so jobs don't mix. Mixing them is a dangerous choice, not a safe default. A collection with no passages returns an empty search. Empty is not a near passage. Don't let the model keep writing on an empty search."),
    ("Sai tên kho là tìm nhầm cả một thời đại.", "The wrong store name searches the wrong era entirely."),
)
K("rag-demo", C6, "s-61b2a0cf9230", "RAG demo", "C6 · RAG", "S3 Demo chưa phải chấm", "Additional Resources - RAG Pre-Requisites",
    ("Một lần RAG in ra câu trả lời chưa phải một lần chấm", "One RAG run that prints an answer is not a scoring run."),
    ("Để buổi demonstration cuối không thành bằng chứng hệ thống đã đúng.", "So the last demonstration session does not become proof the system is right."),
    ("Kho đã có tên. Một buổi demo RAG chỉ cho thấy ống chạy được trên một câu.", "The store already has a name. A RAG demonstration only shows the pipe runs on one question."),
    ("ống chạy", "the pipe runs"), ("chưa chấm", "not scored yet"),
    ("In được một câu là hệ thống sống. Đúng hay sai là việc của các ca: đoạn nào vào prompt, có thêm số không có trong đoạn không.", "Printing a sentence means the system is alive. Right or wrong is the job of the cases: which passage entered the prompt, and whether a number that is not in the passage was added."),
    ("Demo in một câu hoàn tiền nghe ổn. Không ai ghi đoạn nào đã vào. Không có gì để chấm.", "The demo prints a refund sentence that sounds fine. Nobody writes down which passage entered. There is nothing to score."),
    ("Giữ đoạn đã tìm cạnh câu đã viết. Không có cặp đó thì chưa có một ca.", "Keep the retrieved passage next to the written sentence. Without that pair there is no case."),
    ("Ví dụ minh họa: buổi RAG Demonstration chạy một câu. Bạn thêm một ca trong đó đoạn đúng không chứa số tiền, và kiểm tra câu viết có bịa số tiền không. Demo gốc không làm hộ việc đó.", "Illustration: the RAG demonstration runs one question. You add a case where the right passage contains no amount, and you check whether the written sentence invents an amount. The original demo does not do that job for you."),
    [("Lưu đoạn và câu, từng ca.", "Save the passage and the sentence, per case."), ("Một số không có trong đoạn là một ca sai.", "A number that is not in the passage is a failed case."), ("Đừng báo một tỷ lệ từ một lần chạy.", "Don't report a rate from one run.")],
    ("Buổi này là demonstration, cùng loại với buổi tìm kiếm ngữ nghĩa. Nó không cấp bộ ca và không cấp một độ chính xác ngành. Ống chạy là điều kiện cần. Các ca đối chiếu đoạn mới là thước. Không bịa transcript của một khách.", "This session is a demonstration, the same kind as the semantic-search session. It does not hand you a case set and it does not hand you an industry accuracy. A pipe that runs is a necessary condition. Cases that check the passage are the measure. Don't invent a customer's transcript."),
    ("In được câu không phải đã bám file.", "Printing a sentence is not the same as sticking to the file."),
)
K("rag-job", C6, "s-1b2e56e7fd6e", "Answer from the documents", "C6 · RAG", "S1 Bài là trả lời từ tài liệu", "Course Project: RAG",
    ("Bài RAG là trả lời từ tài liệu được giao. Không trả lời từ trí nhớ", "The RAG assignment answers from the documents you were given. Not from memory."),
    ("Để một bài nộp không bị viết bằng những điều khoản mô hình còn nhớ từ chỗ khác.", "So a submission is not written from clauses the model remembers from somewhere else."),
    ("Demo đã không phải chấm. Bài là chỗ các ca phải bám đúng tập tài liệu của đề.", "The demo was not the scoring. The assignment is where the cases must stick to the documents in the brief."),
    ("trong tài liệu được giao", "in the given documents"), ("từ trí nhớ", "from memory"),
    ("Nếu một điều khoản không nằm trong tập tài liệu của bài, câu trả lời không được lấy nó từ chỗ khác, kể cả từ một lần huấn luyện.", "If a clause is not in the assignment's documents, the answer may not take it from somewhere else, including from a training run."),
    ("Đề là các văn bản được giao. Một điều luật bạn «nhớ» không nằm trong tập đó thì không được viết vào câu trả lời như thể nó ở trong tập.", "The brief is the documents you were given. A rule you “remember” that is not in that set may not be written into the answer as if it were in the set."),
    ("Không có trong tập: nói không thấy trong tập. Đừng bổ sung từ trí nhớ.", "Not in the set: say it is not in the set. Don't add it from memory."),
    ("Ví dụ minh họa: bài nói RAG trên các văn bản được giao. Một câu trả lời dẫn một điều khoản không có trong các văn bản đó là một câu ngoài bài, dù điều khoản đó có thật ở ngoài đời.", "Illustration: the assignment says RAG on the documents you were given. An answer that cites a clause which is not in those documents is outside the assignment, even if the clause is real somewhere else."),
    [("Mỗi câu trỏ một đoạn trong tập được giao.", "Each sentence points at a passage in the given set."), ("Không trỏ được: ghi không thấy.", "If you cannot point, write that it is not there."), ("Đừng dán thêm tài liệu lạ cho câu trả lời dễ hơn.", "Don't paste in a strange document to make the answer easier.")],
    ("Sổ này không chứa đề bài và không chứa các văn bản. Ý chỉ là: nguồn của bài là tập được giao, index phải là index của tập đó, và một số không có trong đoạn là một lần sai. Buổi chi tiết phía sau là chỗ làm, không phải một ý thứ hai. Không bịa nội dung các văn bản.", "This notebook does not contain the brief and does not contain the documents. The idea is only: the source of the assignment is the set you were given, the index has to be the index of that set, and a number that is not in the passage is a failure. The detail session after this is where the work happens, not a second idea. Don't invent the contents of the documents."),
    ("Nhớ một điều khoản không có trong tập là ra ngoài bài.", "Remembering a clause that is not in the set is outside the assignment."),
)

# Images
K("im-grid", C6, "s-ab1d2c5f64a9", "An image is a grid", "C6 · Ảnh", "S1 Một lưới số", "Image Generation using Stable Diffusion",
    ("Một ảnh là một lưới số. Chưa phải một sự thật", "An image is a grid of numbers. Not yet a fact."),
    ("Để một bức ảnh sinh ra không được dùng như một biên bản.", "So a generated picture is not used as a record."),
    ("Chữ đã là token. Ảnh là các số trên một lưới, và một mô hình sinh viết các số đó.", "Text was already tokens. An image is numbers on a grid, and a generative model writes those numbers."),
    ("một lưới số", "a grid of numbers"), ("không phải biên bản", "not a record"),
    ("Mỗi ô lưới là một giá trị màu. Mô hình tạo các giá trị đó. Nó không chụp một nơi có thật chỉ vì câu chữ nhắc tên nơi đó.", "Each cell of the grid is a color value. The model creates those values. It does not photograph a real place just because the text names the place."),
    ("Một ảnh «cửa hàng của mình» do mô hình viết không phải ảnh cửa hàng, trừ khi bạn đưa ảnh cửa hàng vào và vẫn phải kiểm.", "A picture of “our shop” that the model wrote is not a picture of the shop, unless you passed a picture of the shop in, and you still have to check."),
    ("Gọi là một lưới đã sinh. Đừng gọi là một tấm ảnh tư liệu.", "Call it a generated grid. Don't call it a documentary photo."),
    ("Ví dụ minh họa: prompt nhắc một góc phố. Ảnh ra có một góc phố. Góc phố đó không phải một địa chỉ bạn có thể gửi khách đến, dù biển hiệu trông thật.", "Illustration: the prompt mentions a street corner. The picture shows a street corner. That corner is not an address you can send a customer to, even if the sign looks real."),
    [("Không dùng ảnh sinh làm bằng chứng địa điểm, người, hoặc số liệu.", "Don't use a generated picture as evidence of a place, a person, or a figure."), ("Ảnh tư liệu là ảnh được chụp và được ghi nguồn.", "A documentary photo is a photo that was taken and whose source is recorded."), ("Một lưới đẹp không thêm một sự thật.", "A pretty grid adds no fact.")],
    ("Độ phân giải là số ô. Nhiều ô không phải nhiều sự thật. Một chữ trên biển trong ảnh sinh hay sai vì chữ cũng chỉ là các ô, không phải một xâu đã được tra. Đây cùng họ với token kế tiếp: hợp lệ để nhìn, không phải một khóa chính.", "Resolution is the number of cells. More cells are not more truth. A word on a sign in a generated picture is often wrong because the word is also just cells, not a string that was looked up. Same family as the next token: valid to look at, not a primary key."),
    ("Trông như ảnh không phải đã được chụp.", "Looking like a photo is not the same as having been taken."),
)
K("im-vae", C6, "s-ab1d2c5f64a9", "VAE", "C6 · Ảnh", "S1 Bản nén bị mờ", "Image Generation using Stable Diffusion",
    ("VAE giữ cái chung. Bản dựng lại bị mờ vì phần riêng đã bị bỏ", "A VAE keeps what is common. The reconstruction is blurry because the particular was dropped."),
    ("Để một bản giải nén không bị gọi là ảnh gốc còn đủ chi tiết.", "So a decoded image is not called the original with all its detail."),
    ("Ảnh là một lưới. VAE nén lưới đó thành một vectơ ngắn hơn, rồi dựng lại.", "An image is a grid. A VAE compresses that grid into a shorter vector, then builds it back."),
    ("giữ cái chung", "keeps what is common"), ("mất cái riêng", "the particular is gone"),
    ("Bộ mã hóa nén. Bộ giải nén dựng một lưới gần. Những chi tiết ít gặp bị hy sinh vì chỗ trong vectơ không đủ.", "The encoder compresses. The decoder builds a nearby grid. Rare details are sacrificed because the vector does not have room."),
    ("Một khuôn mặt cụ thể sau một vòng nén-giải có thể còn giống một khuôn mặt, mất nốt ruồi. Đó không phải ảnh gốc.", "A specific face after a compress-and-decode can still look like a face, and lose a mole. That is not the original photo."),
    ("Đừng dùng bản giải nén làm bản lưu trữ.", "Don't use the decoded image as the archive copy."),
    ("Ví dụ minh họa: ảnh biển hiệu có một chữ nhỏ. Sau VAE chữ đó thành một vệt. Không phải «phông chữ nghệ thuật». Là chi tiết đã bị bỏ khi nén.", "Illustration: a sign photo with one small word. After the VAE the word becomes a smear. That is not an artistic typeface. The detail was dropped in the compression."),
    [("Giữ file gốc nếu bạn cần chi tiết.", "Keep the original file if you need the detail."), ("Bản mờ là bản đã mất thông tin, không phải bản xưa hơn.", "A blurry version is a version that lost information, not an older version."), ("Đừng đọc một chữ trên bản đã giải nén như thể chữ đó còn nguyên.", "Don't read a word on the decoded image as if the word were intact.")],
    ("VAE học một phân phối của các lưới, không học từng tấm ảnh của bạn như một khóa. Không gian nén ép những ảnh gần nhau lại gần. Dựng lại là một ảnh hợp lý trong vùng đó, thường mềm hơn, vì cái riêng không còn trong mã. Mờ ở đây là mất thông tin, không phải một hiệu ứng bạn nên tin.", "A VAE learns a distribution of grids. It does not learn each photo of yours as a key. The compressed space pushes nearby images together. A reconstruction is a plausible image in that region, usually softer, because the particular is no longer in the code. Blur here is lost information, not an effect you should trust."),
    ("Mờ vì đã bỏ bớt. Không phải vì máy ảnh rung.", "It is blurry because something was dropped. Not because the camera shook."),
)
K("im-gan", C6, "s-ab1d2c5f64a9", "GAN", "C6 · Ảnh", "S1 Kẻ giả và người chê", "Image Generation using Stable Diffusion",
    ("GAN là một kẻ giả và một người chê. Người chê gật không phải đời thực gật", "A GAN is a forger and a critic. The critic nodding is not the world nodding."),
    ("Để một ảnh «qua được người chê» không thành một ảnh đã xảy ra.", "So a picture that “got past the critic” is not a picture of something that happened."),
    ("VAE dựng lại từ một mã. GAN có hai mạng: một mạng viết ảnh, một mạng phân biệt ảnh viết và ảnh thật trong tập.", "A VAE reconstructs from a code. A GAN has two networks: one writes pictures, one tells written pictures from pictures that were real in the training set."),
    ("qua mặt người chê", "gets past the critic"), ("không phải đã xảy ra", "not something that happened"),
    ("Generator giả. Discriminator chê. Khi kẻ giả qua mặt được người chê, ảnh trông giống tập luyện. Tập luyện không phải thế giới hôm nay.", "The generator forges. The discriminator criticizes. When the forger gets past the critic, the picture looks like the training set. The training set is not the world today."),
    ("Một ảnh sản phẩm qua được discriminator vẫn có thể là một sản phẩm không có trong catalog của bạn.", "A product picture that gets past the discriminator can still be a product that is not in your catalog."),
    ("«Giống ảnh thật» là giống tập. Kiểm catalog nếu bạn định bán thứ trong ảnh.", "“Looks like a real photo” means it looks like the set. Check the catalog if you plan to sell what is in the picture."),
    ("Ví dụ minh họa: tập luyện có nhiều ảnh giày. GAN viết một đôi giày không có mã. Người chê không bắt được. Kho của bạn vẫn không có đôi đó.", "Illustration: the training set has many shoe photos. The GAN writes a pair of shoes with no code. The critic does not catch it. Your warehouse still does not have that pair."),
    [("Đừng nhập kho một sản phẩm chỉ vì ảnh qua được GAN.", "Don't add a product to the warehouse just because the picture got past the GAN."), ("Người chê là một mạng, không phải một kiểm kê.", "The critic is a network, not an inventory check."), ("Muốn đúng mã sản phẩm thì hỏi catalog, như chặng ShopAssist.", "If you want the right product code, ask the catalog, as in the ShopAssist stage.")],
    ("Hai mạng cùng học và cùng có thể cùng sai: người chê lười, kẻ giả viết một kiểu ảnh hẹp mà người chê không còn phân biệt. Đó là một thất bại bên trong trò chơi của chúng, không phải một chứng nhận. Ảnh GAN không có một log «đã chụp ở đâu».", "The two networks learn together and can be wrong together: the critic gets lazy, the forger writes a narrow kind of picture the critic no longer separates. That is a failure inside their game, not a certificate. A GAN picture has no log of “where it was taken”."),
    ("Qua mặt người chê không phải qua mặt kho.", "Getting past the critic is not getting past the warehouse."),
)
K("im-diff", C6, "s-ab1d2c5f64a9", "Diffusion", "C6 · Ảnh", "S1 Gỡ nhiễu", "Image Generation using Stable Diffusion",
    ("Diffusion học cách gỡ nhiễu. Nó không tra một kho ảnh", "Diffusion learns how to undo noise. It does not look up a photo library."),
    ("Để một ảnh Stable Diffusion không bị kể như một ảnh đã lưu trong máy.", "So a Stable Diffusion picture is not told as a photo that was stored on the machine."),
    ("GAN là một trò giả và chê. Diffusion đi một đường khác: thêm nhiễu vào ảnh, rồi học gỡ nhiễu đó.", "A GAN is a forge-and-critic game. Diffusion takes another path: add noise to an image, then learn to undo that noise."),
    ("gỡ nhiễu", "undo noise"), ("không tra kho", "not a library lookup"),
    ("Xuất phát từ nhiễu, mỗi bước bớt nhiễu một chút, ra một lưới trông như ảnh. Không bước nào là một câu SELECT.", "Start from noise, each step removes a little noise, and you get a grid that looks like a photo. No step is a SELECT."),
    ("Nhắc tên một cửa hàng không làm bước gỡ nhiễu mở file ảnh cửa hàng đó.", "Naming a shop does not make the denoising step open that shop's photo file."),
    ("Gọi là một lưới đã gỡ nhiễu. Kiểm nếu bạn định dùng nó như tư liệu.", "Call it a denoised grid. Check it if you plan to use it as a record."),
    ("Ví dụ minh họa: prompt một bao bì. Ảnh ra có một bao bì. Mã vạch trên bao bì là các ô nhiễu còn lại, không phải mã trong hệ thống.", "Illustration: a prompt of a package. The picture shows a package. The barcode on the package is leftover noisy cells, not the code in the system."),
    [("Đừng đọc chữ hoặc mã trên ảnh diffusion như dữ liệu.", "Don't read words or codes on a diffusion picture as data."), ("Muốn ảnh thật của sản phẩm thì lấy ảnh đã chụp.", "If you want a real product photo, take the photo that was shot."), ("Bước gỡ nhiễu không có #N/A. Nó luôn ra một lưới.", "A denoising step has no #N/A. It always emits a grid.")],
    ("Stable Diffusion thuộc họ này: gỡ nhiễu trong một không gian đã nén, thường là không gian của một VAE, nên chi tiết chữ càng dễ hỏng. Một guidance scale kéo ảnh về phía prompt mạnh hơn. Kéo mạnh không làm prompt thành sự thật. Không có bước nào đối chiếu catalog.", "Stable Diffusion is in this family: denoising in a compressed space, often a VAE's space, so text details break even more easily. A guidance scale pulls the picture toward the prompt more strongly. Pulling harder does not make the prompt true. No step checks the catalog."),
    ("Luôn ra được một ảnh. Đó không phải một dấu hiệu đã tìm thấy.", "It always manages to emit a picture. That is not a sign that it found one."),
)
K("im-txt", C6, "s-a96de1b7f914", "Text steers", "C6 · Ảnh", "S2 Chữ chỉ lái", "Image Generation using Stable Diffusion",
    ("Prompt lái bức ảnh. Nó không chứng nhận bức ảnh", "The prompt steers the picture. It does not certify the picture."),
    ("Để một tên sản phẩm trong prompt không thành một giấy phép dùng ảnh đó cho sản phẩm.", "So a product name in the prompt does not become a license to use that picture for the product."),
    ("Diffusion đã luôn ra một lưới. Prompt là cái lái lưới đó, không phải một biên bản kiểm.", "Diffusion already always emits a grid. The prompt is what steers that grid, not an inspection record."),
    ("lái", "steers"), ("không chứng nhận", "does not certify"),
    ("Một prompt nói chủ đề, kiểu, và các thứ không muốn. Ảnh ra bám các chữ đó theo cách mô hình biết. Nó không ký nhận ảnh là hàng thật, người thật, hay thương hiệu của bạn.", "A prompt says the subject, the style, and what you don't want. The picture follows those words the way the model knows how. It does not sign that the picture is real stock, a real person, or your brand."),
    ("Gõ tên một sản phẩm của bạn. Ảnh có thể mang một logo gần giống, sai chi tiết, và không phải file nhận diện đã duyệt.", "Type your product's name. The picture may carry a near-logo, wrong in the details, and it is not the approved identity file."),
    ("Dùng ảnh sinh như một phác. Duyệt bằng mắt người và bằng tài sản thật. Đừng để prompt tự duyệt.", "Use a generated picture as a sketch. Approve it with a person and with the real assets. Don't let the prompt approve itself."),
    ("Ví dụ minh họa: buổi PixxelCraft trong giáo trình là một sản phẩm minh họa, không phải một giấy chứng nhận. Prompt một bao bì không sinh ra một bao bì đã in. Sổ không bịa thông số của sản phẩm đó.", "Illustration: the PixxelCraft session in the syllabus is an illustrated product, not a certificate. A package prompt does not produce a printed package. This notebook does not invent that product's specifications."),
    [("Prompt ghi cái bạn muốn lái, không ghi cái bạn muốn chứng nhận.", "The prompt states what you want to steer, not what you want certified."), ("Chữ trên ảnh: coi là hỏng cho đến khi người đọc được.", "Words on the picture: treat them as broken until a person can read them."), ("Đưa vào quảng cáo: đối chiếu logo và sản phẩm thật, ngoài mô hình.", "Before an ad: check the logo and the real product, outside the model.")],
    ("Guidance kéo mạnh về prompt làm ảnh «nghe lời» hơn và vẫn có thể sai sự thật một cách rất nghe lời. Negative prompt chỉ là thêm một hướng để tránh, không phải một bộ lọc pháp lý. Ảnh có người thật hoặc thương hiệu người khác là một câu hỏi quyền, không được giải bằng cách thêm chữ «official» vào prompt.", "Stronger guidance toward the prompt makes the picture more “obedient” and it can still be obediently false. A negative prompt is only another direction to avoid, not a legal filter. A picture of a real person or of someone else's brand is a rights question, and it is not solved by adding the word “official” to the prompt."),
    ("Thêm chữ official không ra một văn bản official.", "Adding the word official does not produce an official document."),
)

# LangChain
K("lc-tpl", C6, "s-508f987c6590", "Templates", "C6 · LangChain", "S1 Khuôn có chỗ trống", "LangChain",
    ("Một template là một khuôn với các chỗ trống. Trống thì đừng để mô hình tự điền nguồn", "A template is a form with blanks. If a blank is empty, don't let the model invent the source."),
    ("Để một biến prompt thiếu không bị thay bằng trí nhớ của mô hình.", "So a missing prompt variable is not replaced by the model's memory."),
    ("Prompt đã là việc, ngữ cảnh, dạng. Template là cách sản phẩm điền các chỗ đó từ dữ liệu, không phải từ tay mỗi lần.", "A prompt was already a task, a context, and a shape. A template is how the product fills those from data, not by hand every time."),
    ("điền từ dữ liệu", "filled from data"), ("trống và bịa", "empty, then invented"),
    ("Template có các biến. Biến không được truyền thì chỗ đó trống hoặc lỗi, tùy cách bạn viết. Đừng bắt mô hình «tự hiểu chỗ trống».", "A template has variables. A variable you don't pass is empty or an error, depending on how you wrote it. Don't ask the model to “understand the blank”."),
    ("Biến `policy` không được truyền. Mô hình vẫn viết một chính sách. Đó là một chính sách không nguồn.", "The `policy` variable is not passed. The model still writes a policy. That policy has no source."),
    ("Thiếu biến thì dừng, hoặc nói thiếu. Đừng gọi model.", "If a variable is missing, stop, or say it is missing. Don't call the model."),
    ("Ví dụ minh họa: khuôn «chỉ dùng đoạn sau: {passage}». Passage rỗng mà vẫn gọi thì mọi câu sau là ngoài RAG, dù code nằm trong một thư viện tên LangChain.", "Illustration: the form “use only the following passage: {passage}”. An empty passage that still gets called means every later sentence is outside RAG, even if the code sits in a library named LangChain."),
    [("Liệt kê biến bắt buộc.", "List the required variables."), ("Thiếu một biến bắt buộc: đừng gọi.", "Missing a required variable: don't call."), ("Đừng nhét một giá trị mặc định là một sự thật bịa.", "Don't put a default value that is an invented fact.")],
    ("Buổi LangChain trong giáo trình là optional. Thư viện này giúp xâu chuỗi, không thêm một sự thật. Một template là một chuỗi có lỗ. Lỗ được điền bằng một chuỗi khác. Không có kiểm nào bên trong dấu ngoặc nhọn. Kiểm nằm ở sản phẩm: đủ biến, đúng nguồn, đúng dạng.", "The LangChain session in the syllabus is optional. The library helps you chain things. It adds no fact. A template is a string with holes. A hole is filled with another string. There is no check inside the braces. The check lives in the product: the variables are present, the source is right, the shape is right."),
    ("Khuôn không biết lỗ đó có đúng tài liệu không.", "The form does not know whether the hole is the right document."),
)
K("lc-parse", C6, "s-508f987c6590", "Parsers", "C6 · LangChain", "S1 Khuôn đầu ra có thể vỡ", "LangChain",
    ("Parser đòi một dạng. Model không nghe thì parser vỡ", "A parser demands a shape. If the model does not comply, the parser breaks."),
    ("Để một lần vỡ dạng không bị bắt thành một kết quả mặc định trông như thật.", "So a broken shape is not caught and turned into a default that looks real."),
    ("Template đã điền đầu vào. Parser đọc đầu ra theo một dạng. Vỡ dạng là một lỗi, không phải một câu trả lời yếu.", "The template already filled the input. A parser reads the output against a shape. A broken shape is an error, not a weak answer."),
    ("đúng dạng", "the shape holds"), ("vỡ thì dừng", "if it breaks, stop"),
    ("Bạn xin JSON hoặc một bảng các trường. Model viết một đoạn văn. Parser không đọc được. Đó là lúc dừng.", "You ask for JSON or a table of fields. The model writes a paragraph. The parser cannot read it. That is when you stop."),
    ("Bắt lỗi rồi điền `{\"price\": 0}` là biến một lần vỡ thành một giá 0. Khách có thể bị thu 0.", "Catch the error and fill `{\"price\": 0}` and you turn one break into a price of 0. A customer might be charged 0."),
    ("Vỡ dạng: báo lỗi. Đừng thay bằng một số.", "A broken shape: raise an error. Don't substitute a number."),
    ("Ví dụ minh họa: dạng yêu cầu là có hoặc không kèm đúng mã. Model viết «tôi nghĩ là có, khoảng 2 triệu». Parser vỡ. Kết quả đúng của hệ thống là lỗi dạng, không phải «có».", "Illustration: the required shape is yes or no plus an exact code. The model writes “I think yes, about 2 million”. The parser breaks. The correct system result is a shape error, not “yes”."),
    [("Dạng phải kiểm được bằng máy.", "The shape has to be checkable by a machine."), ("Lỗi parser đi ra ngoài như một lỗi, không như một giá trị.", "A parser error leaves as an error, not as a value."), ("Đừng retry vô hạn. Trần số lần, rồi dừng.", "Don't retry forever. Cap the attempts, then stop.")],
    ("Một output parser là một giao kèo dạng, cùng ý với format trong prompt. Nó không kiểm sự thật của các trường. JSON hợp lệ vẫn có thể chứa một giá không có trong catalog. Việc đó là của log công cụ, không phải của parser. Nuốt lỗi parser là mất dấu một lần model không nghe dạng.", "An output parser is a contract about shape, the same idea as format in the prompt. It does not check whether the fields are true. Valid JSON can still contain a price that is not in the catalog. That job belongs to the tool log, not to the parser. Swallowing a parser error loses the trace of a time the model did not follow the shape."),
    ("Vỡ dạng mà thành số 0 là một quyết định bạn vừa bịa.", "A broken shape that becomes 0 is a decision you just invented."),
)
K("lc-agent", C6, "s-508f987c6590", "Chain and agent", "C6 · LangChain", "S1 Một đường cố định hay một vòng chọn", "LangChain",
    ("Chain là một đường đã vẽ. Agent tự chọn bước sau. Cả hai đều cần trần", "A chain is a path you drew. An agent picks the next step. Both need a cap."),
    ("Để một agent không được chạy mãi vì còn một công cụ để gọi.", "So an agent is not allowed to run forever because there is still a tool to call."),
    ("Parser đã dừng khi vỡ dạng. Agent là chỗ vòng lặp có thể không tự dừng.", "The parser already stops when the shape breaks. An agent is where a loop might not stop itself."),
    ("đường đã vẽ", "a path you drew"), ("tự chọn, có trần", "it chooses, with a cap"),
    ("Chain gọi các bước theo thứ tự bạn viết: khuôn, model, parser, có thể một công cụ. Agent chọn công cụ kế tiếp dựa trên chữ nó vừa viết.", "A chain calls steps in the order you wrote: template, model, parser, maybe a tool. An agent chooses the next tool from the text it just wrote."),
    ("Agent được phép gọi catalog rồi gọi nữa. Không có trần thì một lần hỏi tồn kho thành hai mươi lần gọi và một hóa đơn.", "An agent is allowed to call the catalog and then call it again. With no cap, one stock question becomes twenty calls and a bill."),
    ("Chain khi đường đã rõ. Agent khi bước sau tùy câu hỏi. Cả hai có số bước tối đa.", "A chain when the path is clear. An agent when the next step depends on the question. Both have a maximum number of steps."),
    ("Ví dụ minh họa: tra một mã là một chain hai bước, catalog rồi trả lời. Một câu hỏi mở cần chọn giữa catalog và chính sách thì mới là agent, và dừng sau vài bước dù chưa «hài lòng».", "Illustration: looking up one code is a two-step chain, catalog then answer. An open question that must choose between catalog and policy is an agent, and it stops after a few steps even if it is not “satisfied”."),
    [("Đường cố định: viết chain, đừng mở agent.", "A fixed path: write a chain. Don't open an agent."), ("Agent: ghi trần số bước và trần số lần gọi từng công cụ.", "An agent: write a cap on steps and a cap on calls to each tool."), ("Hết trần: trả về chưa xong, đừng bịa nốt câu.", "When the cap is hit: return unfinished. Don't invent the rest of the sentence.")],
    ("Agent không thông minh hơn chain. Nó chỉ được phép rẽ. Mỗi nhánh rẽ là một lần tốn token và một lần có thể gọi nhầm công cụ. ReAct là kiểu vòng này. Trần bước là constraint của sản phẩm. Không có trần thì bạn không có một bài toán tối ưu, bạn có một cái hố. LangChain không thêm trần hộ nếu bạn không viết.", "An agent is not smarter than a chain. It is only allowed to branch. Each branch spends tokens and can call the wrong tool. ReAct is this kind of loop. The step cap is a product constraint. With no cap you don't have an optimization problem, you have a hole. LangChain does not add the cap for you if you don't write it."),
    ("Tự chọn bước sau mà không có trần là một vòng không cửa ra.", "Choosing the next step with no cap is a loop with no exit."),
)

